#!/usr/bin/env python3
"""Safely create connected MedOrbits pages and supporting repository files.

Creates missing files only by default. Review generated material before publishing.
"""
from __future__ import annotations
import argparse, json, sys
from datetime import datetime, timezone
from pathlib import Path

VERSION = "1.0.0"
EXCLUDED = {".git", "node_modules", ".venv", "venv", "__pycache__", "dist", "build", "coverage"}

CSS = r'''/* MedOrbits connected-page design system */
:root{color-scheme:light;--ink:#19253a;--navy:#102b46;--gold:#c49a52;--sand:#f3eadb;--mist:#e8f0f8;--sage:#e3eee7;--lav:#eee8f7;--peach:#f8e8dd;--line:#c8d4df;--radius:22px;--shadow:0 18px 50px #102b461c}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);font:16px/1.65 Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:linear-gradient(135deg,#eaf1f8,#f4eadb 52%,#e6efe9)}a{color:#164f86;text-underline-offset:.2em}a:hover{color:#8a5c19}a:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.skip{position:absolute;left:-9999px}.skip:focus{left:1rem;top:1rem;z-index:50;background:var(--sand);padding:.8rem}.header{position:sticky;top:0;z-index:20;background:#e8f0f8ed;backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}.nav{max-width:1180px;margin:auto;padding:.8rem 1rem;display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}.brand{font-weight:900;letter-spacing:.06em;color:var(--navy);text-decoration:none}.links{display:flex;gap:.85rem;flex-wrap:wrap}.links a{font-size:.9rem;font-weight:750;text-decoration:none}.wrap{width:min(1180px,calc(100% - 2rem));margin:auto}.hero{position:relative;overflow:hidden;padding:clamp(3rem,8vw,6.5rem) 0}.hero:before,.hero:after{content:"";position:absolute;border-radius:50%;pointer-events:none;animation:float 12s ease-in-out infinite alternate}.hero:before{width:18rem;height:18rem;right:3%;top:4%;background:#cbdcf0a8}.hero:after{width:12rem;height:12rem;right:26%;bottom:-4rem;background:#e8d4b49c;animation-delay:-5s}.hero-inner{position:relative;z-index:1;max-width:850px}.eyebrow{font-size:.78rem;text-transform:uppercase;letter-spacing:.16em;font-weight:850;color:#765522}.hero h1{font-size:clamp(2.25rem,6vw,4.8rem);line-height:1.04;letter-spacing:-.045em;margin:.7rem 0 1rem}.hero p{max-width:720px;color:#45546b;font-size:1.1rem}.actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.4rem}.btn{display:inline-block;padding:.8rem 1.1rem;border-radius:999px;background:var(--navy);color:#f6eddf;font-weight:800;text-decoration:none}.btn.alt{background:var(--sand);color:var(--navy);border:1px solid var(--line)}.section{padding:3rem 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr));gap:1rem}.card{padding:1.3rem;border:1px solid #c8d4df;border-radius:var(--radius);background:linear-gradient(145deg,#f3eadb,#e8f0f8);box-shadow:var(--shadow);min-width:0}.card:nth-child(3n+2){background:linear-gradient(145deg,var(--sage),var(--mist))}.card:nth-child(3n){background:linear-gradient(145deg,var(--lav),var(--peach))}.card h3{margin-top:0;line-height:1.25}.card p{color:#59677d}.card a{font-weight:800}.pill{display:inline-block;border-radius:999px;background:#dce8f5;padding:.2rem .65rem;font-size:.78rem;font-weight:800}.callout{background:var(--sand);border-left:4px solid var(--gold);padding:1rem 1.2rem;border-radius:0 14px 14px 0}.search{width:100%;max-width:560px;padding:.85rem 1rem;border:1px solid var(--line);border-radius:12px;background:var(--mist);font:inherit}.footer{background:var(--navy);color:var(--mist);padding:2.5rem 0;margin-top:3rem}.footer a{color:#f2d7a5}.footgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:1rem}.footer ul{list-style:none;padding:0}.footer li{margin:.35rem 0}.small{font-size:.9rem;color:#c6d4e4}@keyframes float{to{transform:translate(-18px,16px) rotate(8deg)}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important}}@media(max-width:600px){.nav{align-items:flex-start}.hero{padding:3rem 0}}
'''
JS = r'''(function(){"use strict";const input=document.querySelector('[data-search]'),status=document.querySelector('[data-search-status]');if(input&&status){const cards=[...document.querySelectorAll('[data-search-card]')];input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let n=0;cards.forEach(card=>{const ok=!q||card.textContent.toLowerCase().includes(q);card.hidden=!ok;if(ok)n++});status.hidden=false;status.textContent=q?`${n} result(s) found.`:`Showing ${n} items.`})}document.querySelectorAll('[data-year]').forEach(el=>el.textContent=String(new Date().getFullYear()))})();'''

PAGES = {
"medical-admissions": ("Medical Admissions Guide", "Admissions planning", "Understand the medical admissions journey.", "Use this checklist to organise your research. Eligibility, exam rules, counselling schedules and seat availability can change; verify current details with official notices.", [("Eligibility and entrance exams","Check the current official information bulletin and eligibility rules.","/pages/courses.html"),("Counselling and choices","Use the applicable counselling authority portal, schedule and seat matrix.","/pages/colleges.html"),("Documents and deadlines","Verify required documents, formats and validity with the authority.","/pages/help-centre.html")]),
"colleges": ("College Research Directory", "Institution research", "Compare colleges using verified information.", "Research recognition, course availability, fees and facilities. This starter directory intentionally does not invent institution records or current fees.", [("Recognition and affiliation","Confirm programme status with the relevant official regulator or university.","/pages/medical-admissions.html"),("Fees and expenses","Use the latest official prospectus or fee order.","/pages/courses.html"),("Location and facilities","Check address, facilities and accommodation directly.","/pages/contact-support.html")]),
"courses": ("Courses and Study Pathways", "Course catalogue", "Explore education pathways before you apply.", "Course structures, entry requirements and recognition vary. Verify official prospectuses before making decisions.", [("MBBS and medical","Review current entrance exam and counselling authority guidance.","/pages/medical-admissions.html"),("BDS and allied health","Compare recognition, practical training and registration requirements.","/pages/colleges.html"),("AYUSH and other pathways","Check the relevant regulator and counselling notices.","/pages/help-centre.html")]),
"careers": ("Careers and Recruitment Support", "Career development", "Build a practical plan for your next opportunity.", "Map qualifications and skills to target roles. Treat vacancies as valid only when employer and application details can be verified.", [("Career planning","Identify role requirements, skill gaps and a learning plan.","/pages/courses.html"),("CV and interview preparation","Prepare evidence-based experience statements and role-specific answers.","/pages/help-centre.html"),("Verified opportunities","Check employer identity, job description and closing date.","/pages/contact-support.html")]),
"scholarships": ("Scholarships and Financial Aid", "Funding research", "Find funding opportunities and verify every condition.", "Eligibility, award amounts and application windows change. Use official provider pages and retain the current terms.", [("Eligibility and documents","Check conditions in the official scholarship notice.","/pages/help-centre.html"),("Application calendar","Record deadlines, documents and confirmation receipts.","/pages/courses.html"),("Avoid scams","Do not pay unverified agents or share sensitive documents unofficially.","/pages/contact-support.html")]),
"study-abroad": ("Study Abroad Planning", "International education", "Plan international study with reliable sources.", "Confirm recognition, admission conditions, visa rules and total costs using official institution and government sources.", [("University and programme","Verify accreditation and entry conditions directly.","/pages/colleges.html"),("Budget and funding","Estimate tuition, living costs, insurance and travel.","/pages/scholarships.html"),("Visa and compliance","Use official immigration guidance for the destination.","/pages/help-centre.html")]),
"help-centre": ("Help Centre", "Support and resources", "Get organised before requesting guidance.", "Prepare your target course, location, academic stage and deadline. Do not send passwords, OTPs or unnecessary sensitive documents.", [("Admissions questions","Include the course, academic year and authority.","/pages/medical-admissions.html"),("Documents and applications","Use official checklists and redact sensitive details.","/pages/colleges.html"),("Contact support","Use verified contact channels and retain reference numbers.","/pages/contact-support.html")]),
"contact-support": ("Contact and Support", "Contact MedOrbits", "Tell us what guidance you need.", "Use contact details verified by your organisation. This generated page does not invent phone numbers, email addresses or response-time promises.", [("Prepare your enquiry","State your programme, academic year, location and question.","/pages/help-centre.html"),("Protect your information","Never send passwords, OTPs or payment PINs.","/pages/help-centre.html"),("Check official sources","Use the relevant authority for deadlines and regulations.","/pages/medical-admissions.html")])}

NAV = ''.join(f'<a href="/pages/{slug}.html">{label}</a>' for slug,label in [("medical-admissions","Admissions"),("colleges","Colleges"),("courses","Courses"),("careers","Careers"),("scholarships","Scholarships"),("study-abroad","Study abroad"),("help-centre","Help")])
FOOT = '''<footer class="footer"><div class="wrap"><div class="footgrid"><div><h2>MedOrbits</h2><p>Education information and guidance.</p></div><div><h3>Admissions</h3><ul><li><a href="/pages/medical-admissions.html">Admissions</a></li><li><a href="/pages/colleges.html">Colleges</a></li><li><a href="/pages/courses.html">Courses</a></li></ul></div><div><h3>Opportunities</h3><ul><li><a href="/pages/scholarships.html">Scholarships</a></li><li><a href="/pages/careers.html">Careers</a></li><li><a href="/pages/study-abroad.html">Study abroad</a></li></ul></div><div><h3>Support</h3><ul><li><a href="/pages/help-centre.html">Help centre</a></li><li><a href="/pages/contact-support.html">Contact</a></li></ul></div></div><p class="small">© <span data-year></span> MedOrbits. Verify official requirements before making decisions.</p></div></footer>'''

def manifest() -> dict[str,str]:
    files = {"assets/css/medorbits-expansion.css":CSS, "assets/js/medorbits-expansion.js":JS}
    for slug,(title,eyebrow,heading,intro,cards) in PAGES.items():
        card_html = ''.join(f'<article class="card" data-search-card><span class="pill">Guide</span><h3>{h}</h3><p>{p}</p><a href="{url}">Read more →</a></article>' for h,p,url in cards)
        files[f"pages/{slug}.html"] = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b46"><meta name="description" content="{intro}"><title>{title} | MedOrbits</title><link rel="stylesheet" href="/assets/css/medorbits-expansion.css"><script src="/assets/js/medorbits-expansion.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><nav class="nav" aria-label="Main navigation"><a class="brand" href="/index.html">MEDORBITS</a><div class="links">{NAV}</div></nav></header><main id="main"><section class="hero"><div class="wrap hero-inner"><span class="eyebrow">{eyebrow}</span><h1>{heading}</h1><p>{intro}</p><div class="actions"><a class="btn" href="/pages/contact-support.html">Request guidance</a><a class="btn alt" href="/assets/data/education-catalog.json">View catalogue data</a></div></div></section><section class="section"><div class="wrap"><h2>Explore this topic</h2><label for="mo-search">Filter guidance cards</label><p><input class="search" id="mo-search" data-search type="search" placeholder="Search this page" aria-describedby="mo-search-status"></p><p class="small" id="mo-search-status" data-search-status aria-live="polite" hidden></p><div class="grid">{card_html}</div><div class="callout" style="margin-top:1.4rem"><strong>Verification note:</strong> This is an informational template. Confirm current rules and claims with official sources.</div></div></section></main>{FOOT}</body></html>'''
    categories = [{"id":s,"title":v[0],"href":f"/pages/{s}.html","status":"editorial-draft"} for s,v in PAGES.items()]
    files["assets/data/education-catalog.json"] = json.dumps({"schemaVersion":"1.0.0","publisher":"MedOrbits","lastReviewed":None,"notice":"Verify official eligibility, fees, deadlines, recognition and availability before publication.","categories":categories},indent=2)+"\n"
    files["assets/data/colleges.json"] = json.dumps({"schemaVersion":"1.0.0","publisher":"MedOrbits","records":[],"notice":"Add verified institutions with official source URLs and review dates."},indent=2)+"\n"
    files["assets/data/courses.json"] = json.dumps({"schemaVersion":"1.0.0","publisher":"MedOrbits","records":[{"id":"mbbs","name":"MBBS","verified":False},{"id":"bds","name":"BDS","verified":False},{"id":"bams","name":"BAMS","verified":False},{"id":"bums","name":"BUMS","verified":False},{"id":"paramedical","name":"Paramedical programmes","verified":False}],"notice":"Verify eligibility and rules with official authorities."},indent=2)+"\n"
    for name,notice in [("scholarships","Add official source URL, eligibility, application window and review date."),("jobs","Add only verified vacancies with employer source, posting date and expiry date.")]:
        files[f"assets/data/{name}.json"] = json.dumps({"schemaVersion":"1.0.0","records":[],"notice":notice},indent=2)+"\n"
    files["api/schemas/education-catalog.schema.json"] = json.dumps({"$schema":"https://json-schema.org/draft/2020-12/schema","title":"MedOrbits Education Catalog","type":"object","required":["schemaVersion","publisher","categories"],"properties":{"schemaVersion":{"type":"string"},"publisher":{"type":"string"},"lastReviewed":{"type":["string","null"],"format":"date"},"notice":{"type":"string"},"categories":{"type":"array","items":{"type":"object","required":["id","title","href","status"],"properties":{"id":{"type":"string"},"title":{"type":"string"},"href":{"type":"string","pattern":"^/"},"status":{"type":"string"}}}}}},indent=2)+"\n"
    files["pages/_shared/page-template.html"] = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MedOrbits Page Template</title><link rel="stylesheet" href="/assets/css/medorbits-expansion.css"><script src="/assets/js/medorbits-expansion.js" defer></script></head><body><header class="header"><nav class="nav"><a class="brand" href="/index.html">MEDORBITS</a><div class="links">{NAV}</div></nav></header><main><section class="hero"><div class="wrap hero-inner"><span class="eyebrow">Reusable template</span><h1>Build a connected education page.</h1><p>Duplicate this template into the appropriate page directory and replace the sample content with verified information.</p></div></section></main>{FOOT}</body></html>'''
    files["docs/REPOSITORY_EXPANSION.md"] = """# MedOrbits Repository Expansion\n\nCreates connected starter pages, shared CSS/JS, JSON catalogues and a JSON Schema.\n\nRun `python tools/expand_medorbits_repository.py --dry-run` to preview. Run without `--dry-run` to create missing files. Existing files are preserved unless `--overwrite` is passed.\n\nGenerated pages are editorial starters, not authoritative admissions, legal or financial advice. Verify all changing facts against primary sources. Root-relative asset links assume deployment at the domain root.\n"""
    return files

def safe_target(root: Path, name: str) -> Path:
    rel=Path(name)
    if rel.is_absolute() or ".." in rel.parts or not rel.parts or any(p in EXCLUDED for p in rel.parts):
        raise ValueError(f"Unsafe target path: {name}")
    target=root/rel
    current=root
    for part in rel.parts:
        current=current/part
        if current.is_symlink(): raise ValueError(f"Symlink target rejected: {name}")
    target.resolve().relative_to(root.resolve())
    return target

def main() -> int:
    parser=argparse.ArgumentParser(description="Create connected MedOrbits pages and assets")
    parser.add_argument("--root",type=Path,default=Path.cwd(),help="Repository root")
    parser.add_argument("--dry-run",action="store_true",help="Preview without writing")
    parser.add_argument("--overwrite",action="store_true",help="Replace manifest files; use cautiously")
    parser.add_argument("--report",type=Path,default=Path("tools/repository-expansion-report.json"),help="Report path inside repository")
    args=parser.parse_args(); root=args.root.expanduser().resolve()
    if not root.is_dir(): parser.error("--root must be an existing directory")
    created=[]; replaced=[]; skipped=[]; planned=[]; errors=[]
    for name,content in sorted(manifest().items()):
        try:
            target=safe_target(root,name)
            if target.exists() and not args.overwrite: skipped.append(name); continue
            planned.append(name)
            if args.dry_run: continue
            target.parent.mkdir(parents=True,exist_ok=True); target=safe_target(root,name)
            existed=target.exists()
            with target.open("w" if args.overwrite else "x",encoding="utf-8",newline="\n") as stream: stream.write(content)
            (replaced if existed else created).append(name)
        except FileExistsError: skipped.append(name)
        except (OSError,ValueError) as exc: errors.append({"file":name,"error":str(exc)})
    report={"tool":"MedOrbits Repository Expander","version":VERSION,"root":str(root),"dry_run":args.dry_run,"overwrite":args.overwrite,"manifest_count":len(manifest()),"planned":planned,"created":created,"replaced":replaced,"skipped_existing":skipped,"errors":errors,"generated_at_utc":datetime.now(timezone.utc).isoformat()}
    if not args.dry_run:
        out=args.report if args.report.is_absolute() else root/args.report
        try:
            out.resolve().relative_to(root)
            if any(p in EXCLUDED for p in out.relative_to(root).parts): raise ValueError("Report path is excluded")
            out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(report,indent=2)+"\n",encoding="utf-8")
            report["report_file"]=str(out.relative_to(root))
        except (OSError,ValueError) as exc:
            errors.append({"file":str(args.report),"error":str(exc)})
    print(json.dumps(report,indent=2,ensure_ascii=False))
    return 1 if errors else 0

if __name__=="__main__": raise SystemExit(main())
